1	import { type Item, insuranceSumOf } from "./claim-office.js";
2	
3	const DEDUCTIBLE_PER_DAMAGE_ENTRY = 100;
4	const PAYOUT_CAP_MULTIPLE = 2;
5	
6	export interface Damage {
7	  readonly itemType: string;
8	  readonly amount: number;
9	}
10	
11	export interface Incident {
12	  readonly cause: string;
13	  readonly damages: readonly Damage[];
14	}
15	
16	export interface Policy {
17	  readonly items: readonly Item[];
18	  readonly insuranceSum: number;
19	  remainingCap: number;
20	}
21	
22	export interface ClaimSettlement {
23	  readonly payout: number;
24	  readonly remainingCap: number;
25	}
26	
27	function roundPayoutInOfficesFavour(payout: number): number {
28	  return Math.floor(payout);
29	}
30	
31	export function policyFor(items: readonly Item[]): Policy {
32	  const insuranceSum = insuranceSumOf(items);
33	  return { items, insuranceSum, remainingCap: insuranceSum * PAYOUT_CAP_MULTIPLE };
34	}
35	
36	// One entry of the incident's `damages` array is one damage, and each one bears
37	// its own deductible -- a single dragon attack that damages a sword and an amulet
38	// deducts 100 G twice, not once. What share of the damage is reimbursable before
39	// the deductible is a separate decision (the special clauses), which no active
40	// example varies yet.
41	function reimbursementFor(damage: Damage): number {
42	  return damage.amount - DEDUCTIBLE_PER_DAMAGE_ENTRY;
43	}
44	
45	// Summing per entry is what makes the deductible per-entry: the incident as a
46	// whole is never the unit the deductible is charged against.
47	function desiredReimbursementFor(incident: Incident): number {
48	  return incident.damages.reduce((sum, damage) => sum + reimbursementFor(damage), 0);
49	}
50	
51	// The cap limits what a single claim pays out, and every payout consumes it:
52	// successive claims against the same policy share one cap.
53	function payoutLimitedToRemainingCap(desiredReimbursement: number, remainingCap: number): number {
54	  return Math.min(desiredReimbursement, remainingCap);
55	}
56	
57	function consumeCap(policy: Policy, payout: number): void {
58	  policy.remainingCap -= payout;
59	}
60	
61	export function settle(policy: Policy, incident: Incident): ClaimSettlement {
62	  const payout = roundPayoutInOfficesFavour(
63	    payoutLimitedToRemainingCap(desiredReimbursementFor(incident), policy.remainingCap),
64	  );
65	  consumeCap(policy, payout);
66	  return { payout, remainingCap: policy.remainingCap };
67	}
